css:
body {
	margin: 0;
	font-family: sans-serif;
}

main.mk-1xqsewl { padding: 16px; }
			.card.mk-1xqsewl { padding: 12px; border: 1px solid #c9c2b4; border-radius: 12px; background: #fbf8f1; }
			.actions.mk-1xqsewl { display: flex; gap: 8px; }
			.lifted.mk-1xqsewl {
				position: relative;
				z-index: 1;
				top: 96px;
				padding: 10px 16px;
				border: 2px solid #1d4ed8;
				border-radius: 10px;
				background: #dbeafe;
				color: #1e3a8a;
				font-family: inherit;
				font-size: 16px;
			}
			.footer.mk-1xqsewl { margin: 12px 0 0; color: #6b645a; }
			.later.mk-1xqsewl {
				display: block;
				width: 100%;
				height: 96px;
				margin-top: 12px;
				padding: 0 0 8px 0;
				border: 0;
				background: #fde68a;
				color: #78350f;
				font-family: inherit;
				font-size: 16px;
				text-align: right;
				vertical-align: bottom;
			}
